import { drizzle } from 'drizzle-orm/node-postgres';
import pg, { Pool } from 'pg';
import * as schema from './schema';

// Force TIMESTAMP WITHOUT TZ (oid 1114) to always be read as UTC regardless of
// the Node.js process timezone. Without this, pg uses the process TZ to interpret
// the raw value, so a dev machine running BST reads the same stored instant as
// 1 hour earlier than a UTC Docker container — causing systematic display drift.
pg.types.setTypeParser(1114, (val: string) => new Date(val + 'Z'));

// Re-export schema types and table objects — safe to import anywhere
export * from './schema';

// Export inferred types for all tables
export type User = typeof schema.users.$inferSelect;
export type NewUser = typeof schema.users.$inferInsert;

export type Session = typeof schema.sessions.$inferSelect;
export type NewSession = typeof schema.sessions.$inferInsert;

export type Flight = typeof schema.flights.$inferSelect;
export type NewFlight = typeof schema.flights.$inferInsert;

export type FlightTime = typeof schema.flightTimes.$inferSelect;
export type NewFlightTime = typeof schema.flightTimes.$inferInsert;

export type FlightNote = typeof schema.flightNotes.$inferSelect;
export type NewFlightNote = typeof schema.flightNotes.$inferInsert;

export type FlightStatusHistory = typeof schema.flightStatusHistory.$inferSelect;
export type NewFlightStatusHistory = typeof schema.flightStatusHistory.$inferInsert;

export type WeatherDatum = typeof schema.weatherData.$inferSelect;
export type NewWeatherDatum = typeof schema.weatherData.$inferInsert;

export type AirportDaylight = typeof schema.airportDaylight.$inferSelect;
export type NewAirportDaylight = typeof schema.airportDaylight.$inferInsert;

export type Airport = typeof schema.airports.$inferSelect;
export type NewAirport = typeof schema.airports.$inferInsert;

export type ScraperLog = typeof schema.scraperLogs.$inferSelect;
export type NewScraperLog = typeof schema.scraperLogs.$inferInsert;

export type AircraftPosition = typeof schema.aircraftPositions.$inferSelect;
export type NewAircraftPosition = typeof schema.aircraftPositions.$inferInsert;

export type PushSubscription = typeof schema.pushSubscriptions.$inferSelect;
export type NewPushSubscription = typeof schema.pushSubscriptions.$inferInsert;

export type HistoricalWeather = typeof schema.historicalWeather.$inferSelect;
export type NewHistoricalWeather = typeof schema.historicalWeather.$inferInsert;

export type NotificationWatermark = typeof schema.notificationWatermark.$inferSelect;
export type NewNotificationWatermark = typeof schema.notificationWatermark.$inferInsert;
export { tryAcquireServiceLock } from './singleton';
export {
  clearAllTimers,
  countFlightsForDate,
  getActiveFlightsToday,
  getEstimatedTimesBatch,
  msSinceLastScrape,
  logSchedulerEvent,
  computeNextInterval,
  shouldSleep,
  computeWakeTime,
  type TimerState,
} from './scheduler';
export { canUpgradeStatus, isTerminalStatus } from './statusPriority';
export { ROUTE_FLIGHT_MINUTES, LOCATION_TO_IATA, routeFlightMinutes, locationToIata } from './constants';
export { GY_TZ, localToUtc, guernseyTodayStr, guernseyTomorrowStr, guernseyHour, nextGuernseyTime, checkTimezoneOffset } from './time';
export type { TimezoneCheckResult } from './time';

export type DbClient = ReturnType<typeof drizzle<typeof schema>>;

let _db: DbClient | null = null;

export function getDb(): DbClient {
  if (_db) return _db;
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is not set');
  // Keep pool small per-service so 6 services don't exhaust PostgreSQL's
  // default max_connections (typically 100). Each service gets up to 5
  // connections; peak total = 30, leaving headroom for admin tools.
  const pool = new Pool({
    connectionString: url,
    max: 5,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000,
  });
  // Enforce UTC session timezone on every connection so that TIMESTAMP WITHOUT TZ
  // values written by pg are stored as UTC wall-clock, consistent with TZ=UTC containers.
  pool.on('connect', (client) => { client.query("SET TIME ZONE 'UTC'").catch(() => {}); });
  _db = drizzle(pool, { schema });
  return _db;
}

// Proxy-based `db` export — lazily initialises the pool on first use.
// Only import this from server-side code (*.server.ts / Node scrapers).
export const db: DbClient = new Proxy({} as DbClient, {
  get(_t, prop) {
    return (getDb() as unknown as Record<string | symbol, unknown>)[prop];
  },
  apply(_t, _this, args) {
    return (getDb() as unknown as (...a: unknown[]) => unknown)(...args);
  },
});

import { db, getDb } from './index';
import { sql } from 'drizzle-orm';

/**
 * Attempt to acquire a PostgreSQL advisory lock for a named service.
 * Uses pg_try_advisory_lock (non-blocking) — returns immediately.
 *
 * Call this at the very start of a service's main() before any HTTP
 * or polling logic. If another instance of the same service is already
 * running, this returns false and the new process should exit cleanly.
 *
 * The lock is automatically released when the PostgreSQL session ends
 * (process exit or connection close).
 *
 * @param serviceName Unique name for the service (e.g. 'guernsey_live', 'fr24_live')
 * @returns true if this process acquired the lock, false if another instance holds it
 */
export async function tryAcquireServiceLock(serviceName: string): Promise<boolean> {
  try {
    // pg_try_advisory_lock(key) — non-blocking, returns boolean.
    // hashtext converts the service name to a stable integer.
    const result = await db.execute(
      sql`SELECT pg_try_advisory_lock(hashtext(${serviceName})) as locked`,
    );
    const locked = (result.rows[0] as { locked: boolean } | undefined)?.locked ?? false;
    return locked;
  } catch (err) {
    // If the query itself fails (DB unreachable), log and fail open.
    // This avoids a bootstrap deadlock: if the DB is down, the service
    // should start anyway so it can log the error and retry.
    console.error(`[singleton] Failed to acquire lock for '${serviceName}':`, err);
    return true; // fail open — let the service start
  }
}

/**
 * Shared scheduler logic for periodic scrapers.
 *
 * Both guernsey-scraper and fr24-scraper use the same DB-driven
 * scheduling pattern: dynamic intervals, sleep/wake decisions,
 * timer management, and scraper log event recording.
 */
import { eq, and, not, inArray, asc, count, desc, max, sql } from 'drizzle-orm';
import { flights, flightTimes, scraperLogs } from './schema';
import { db } from './index';
import type { CircuitBreaker, TimerState } from '@airways/common';

// Re-export TimerState for convenience
export type { TimerState };

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

export function clearAllTimers(timers: TimerState): void {
  for (const key of Object.keys(timers)) {
    const k = key as keyof TimerState;
    if (timers[k]) {
      clearTimeout(timers[k]!);
      timers[k] = null;
    }
  }
}

// ---------------------------------------------------------------------------
// DB helpers
// ---------------------------------------------------------------------------

export async function countFlightsForDate(dateStr: string): Promise<number> {
  try {
    const [{ value }] = await db
      .select({ value: count() })
      .from(flights)
      .where(eq(flights.flightDate, dateStr));
    return value ?? 0;
  } catch {
    return 0;
  }
}

export async function getActiveFlightsToday(
  todayStr: string,
): Promise<
  Array<{
    id: number;
    flightNumber: string;
    scheduledDeparture: Date | null;
    scheduledArrival: Date | null;
    actualDeparture: Date | null;
    actualArrival: Date | null;
    status: string | null;
  }>
> {
  return db
    .select({
      id: flights.id,
      flightNumber: flights.flightNumber,
      scheduledDeparture: flights.scheduledDeparture,
      scheduledArrival: flights.scheduledArrival,
      actualDeparture: flights.actualDeparture,
      actualArrival: flights.actualArrival,
      status: flights.status,
    })
    .from(flights)
    .where(
      and(
        eq(flights.flightDate, todayStr),
        eq(flights.canceled, false),
        // Exclude terminal and diverted statuses
        not(inArray(flights.status, ['Landed', 'Cancelled'])),
        sql`(${flights.status} IS NULL OR LOWER(${flights.status}) NOT LIKE 'diverted%')`,
      ),
    );
}

export async function getEstimatedTimesBatch(
  flightIds: number[],
): Promise<Map<number, { estDep?: Date; estArr?: Date }>> {
  const result = new Map<number, { estDep?: Date; estArr?: Date }>();
  if (flightIds.length === 0) return result;
  try {
    const rows = await db
      .select({
        flightId: flightTimes.flightId,
        timeType: flightTimes.timeType,
        timeValue: flightTimes.timeValue,
      })
      .from(flightTimes)
      .where(
        and(
          inArray(flightTimes.flightId, flightIds),
          inArray(flightTimes.timeType, ['EstimatedBlockOff', 'EstimatedBlockOn']),
        ),
      );
    for (const row of rows) {
      const entry = result.get(row.flightId) ?? {};
      if (row.timeType === 'EstimatedBlockOff') entry.estDep = new Date(row.timeValue);
      if (row.timeType === 'EstimatedBlockOn') entry.estArr = new Date(row.timeValue);
      result.set(row.flightId, entry);
    }
  } catch {
    // Return empty map on error
  }
  return result;
}

export async function msSinceLastScrape(serviceName: string): Promise<number> {
  try {
    const [last] = await db
      .select({ completedAt: scraperLogs.completedAt })
      .from(scraperLogs)
      .where(eq(scraperLogs.service, serviceName as any))
      .orderBy(desc(scraperLogs.completedAt))
